// ──────────────────────────────────────────────
// Otome Forge: the package's fonts as data: URIs (the Engine's CSP allows only `font-src 'self' data:`)
// ──────────────────────────────────────────────
// Source: Google Fonts' CSS2 API, https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,600;1,600
// &family=Nunito+Sans:wght@400;700&family=Caveat:wght@500 — its latin and latin-ext woff2 subsets from fonts.gstatic.com,
// kept unchanged in packages/otome-forge/fonts beside OFL.txt. Nunito Sans is one variable file for both weights.
// The families get Otome-only names, so they never replace or borrow a font the Engine or another package loads.
//
// Regenerated from the repository root, after the files in packages/otome-forge/fonts change, with:
// node -e 'const fs=require("fs"),dir="packages/otome-forge/fonts/",out="packages/otome-forge/src/engine/packages/client/src/features/otome-forge/theme/fonts.ts",mark="// @generated font data\n",src=fs.readFileSync(out,"utf8");fs.writeFileSync(out,src.slice(0,src.lastIndexOf(mark)+mark.length)+"const FONT_DATA = {\n"+fs.readdirSync(dir).filter((f)=>f.endsWith(".woff2")).sort().map((f)=>`  ${JSON.stringify(f)}:\n    "${fs.readFileSync(dir+f).toString("base64")}",`).join("\n")+"\n} as const;\n")'

